	ctx := context.Background()
	st := openTestStore(t)

	batch, created, err := st.CreateBackfill(ctx, sampleBackfill())
	if err != nil {
		t.Fatalf("create: %v", err)
	}
	if !created {
		t.Fatalf("created = false, want true")
